public class Exercise {
    static class Pair<A, B> {
        private final A first;
        private final B second;
        public Pair(A first, B second) {
            this.first = first;
            this.second = second;
        }
        public A getFirst() { return first; }
        public B getSecond() { return second; }
        public Pair<B, A> swap() { return new Pair<>(second, first); }
        public String toString() { return "(" + first + ", " + second + ")"; }
    }

    public static void main(String[] args) {
        Pair<String, Integer> nameAge = new Pair<>("Alice", 30);
        System.out.println("Original: " + nameAge);  // (Alice, 30)
        Pair<Integer, String> swapped = nameAge.swap();
        System.out.println("Swapped: " + swapped);   // (30, Alice)
        System.out.println("First of swapped: " + swapped.getFirst()); // 30 (Integer)
    }
}

