import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Exercise {
    public static <T> void copy(List<? extends T> src, List<? super T> dest) {
        for (T element : src) {
            dest.add(element);
        }
    }

    public static void main(String[] args) {
        List<Integer> source = Arrays.asList(1, 2, 3, 4, 5);
        List<Number> dest = new ArrayList<>();
        copy(source, dest);
        System.out.println("Destination after copy: " + dest); // [1, 2, 3, 4, 5]

        // Also works with matching types:
        List<String> strSrc = Arrays.asList("a", "b", "c");
        List<Object> objDest = new ArrayList<>();
        copy(strSrc, objDest);
        System.out.println("Object dest: " + objDest); // [a, b, c]
    }
}

