import java.util.ArrayList;
import java.util.List;

public class Exercise {
    static class TypeAwareBox<T> {
        private final Class<T> type;
        private T value;

        TypeAwareBox(Class<T> type) { this.type = type; }

        public T createInstance() {
            try {
                return type.getDeclaredConstructor().newInstance();
            } catch (Exception e) {
                throw new RuntimeException("Cannot instantiate " + type.getName(), e);
            }
        }

        public Class<T> getType() { return type; }
    }

    public static void main(String[] args) {
        // instanceof with raw type works; parameterized does not compile:
        List<String> strings = new ArrayList<>();
        strings.add("hello");
        // if (strings instanceof List<String>) {} // COMPILE ERROR
        System.out.println("Is a List: " + (strings instanceof List<?>)); // ok: unbounded wildcard

        // Workaround: pass Class<T> token
        TypeAwareBox<StringBuilder> box = new TypeAwareBox<>(StringBuilder.class);
        StringBuilder sb = box.createInstance();
        sb.append("created via reflection");
        System.out.println("Created: " + sb);
        System.out.println("Type: " + box.getType().getSimpleName()); // StringBuilder
    }
}

