public class Exercise {
    interface Converter<F, T> {
        T convert(F from);
    }

    static class StringToInt implements Converter<String, Integer> {
        public Integer convert(String from) { return Integer.parseInt(from); }
    }

    static class IntToString implements Converter<Integer, String> {
        public String convert(Integer from) { return "Number: " + from; }
    }

    public static void main(String[] args) {
        Converter<String, Integer> strToInt = new StringToInt();
        System.out.println(strToInt.convert("123")); // 123

        Converter<Integer, String> intToStr = new IntToString();
        System.out.println(intToStr.convert(42)); // Number: 42

        // As a lambda (since Converter is a functional interface):
        Converter<Double, Integer> doubleToInt = d -> d.intValue();
        System.out.println(doubleToInt.convert(9.99)); // 9

        // Chain converters:
        String result = intToStr.convert(strToInt.convert("777"));
        System.out.println("Chained: " + result); // Number: 777
    }
}

