import java.util.TreeSet;

public class Exercise {
    static class Student implements Comparable<Student> {
        String name;
        double gpa;
        Student(String name, double gpa) { this.name = name; this.gpa = gpa; }

        @Override
        public int compareTo(Student other) {
            int gpaCmp = Double.compare(this.gpa, other.gpa);
            if (gpaCmp != 0) return gpaCmp;
            return this.name.compareTo(other.name); // tiebreak by name
        }

        public String toString() { return name + "(" + gpa + ")"; }
    }

    public static void main(String[] args) {
        TreeSet<Student> students = new TreeSet<>();
        students.add(new Student("Alice", 3.8));
        students.add(new Student("Bob", 3.5));
        students.add(new Student("Charlie", 3.9));
        students.add(new Student("Diana", 3.5));
        for (Student s : students) {
            System.out.println(s);
        }
        // Bob(3.5), Diana(3.5), Alice(3.8), Charlie(3.9)
    }
}

