import java.io.Serializable;
import java.util.Arrays;
import java.util.List;

public class Exercise {
    public static <T extends Comparable<T> & Serializable> T findMin(List<T> list) {
        if (list.isEmpty()) throw new IllegalArgumentException("List is empty");
        T min = list.get(0);
        for (T item : list) {
            if (item.compareTo(min) < 0) min = item;
        }
        return min;
    }

    static class SortedPair<T extends Comparable<T> & Serializable> {
        private final T first; // always the smaller
        private final T second;
        SortedPair(T a, T b) {
            if (a.compareTo(b) <= 0) { first = a; second = b; }
            else { first = b; second = a; }
        }
        public T getFirst() { return first; }
        public T getSecond() { return second; }
        public String toString() { return "(" + first + ", " + second + ")"; }
    }

    public static void main(String[] args) {
        List<Integer> ints = Arrays.asList(5, 3, 8, 1, 4);
        System.out.println("Min: " + findMin(ints)); // 1

        List<String> words = Arrays.asList("banana", "apple", "cherry");
        System.out.println("Min: " + findMin(words)); // apple

        SortedPair<Integer> pair1 = new SortedPair<>(9, 3);
        System.out.println("SortedPair: " + pair1); // (3, 9)

        SortedPair<String> pair2 = new SortedPair<>("zebra", "ant");
        System.out.println("SortedPair: " + pair2); // (ant, zebra)
    }
}

