import java.util.Arrays;
import java.util.List;

public class Exercise {
    public static void printList(List<?> list) {
        System.out.print("[");
        for (int i = 0; i < list.size(); i++) {
            System.out.print(list.get(i));
            if (i < list.size() - 1) System.out.print(", ");
        }
        System.out.println("]");
    }

    public static int countNulls(List<?> list) {
        int count = 0;
        for (Object elem : list) {
            if (elem == null) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        List<String> strings = Arrays.asList("a", null, "b", null, "c");
        List<Integer> ints = Arrays.asList(1, 2, 3);

        printList(strings); // [a, null, b, null, c]
        printList(ints);    // [1, 2, 3]

        System.out.println("Nulls in strings: " + countNulls(strings)); // 2
        System.out.println("Nulls in ints: " + countNulls(ints));       // 0

        // printList(List<Object>) would NOT compile for List<String>:
        // printListObj(strings); // COMPILE ERROR because List<String> is not List<Object>
        System.out.println("Unbounded wildcard accepts any List");
    }
}

