import java.util.ArrayList;
import java.util.EmptyStackException;

public class Exercise {
    static class Stack<T> {
        private final ArrayList<T> data = new ArrayList<>();

        public void push(T item) { data.add(item); }

        public T pop() {
            if (isEmpty()) throw new EmptyStackException();
            return data.remove(data.size() - 1);
        }

        public T peek() {
            if (isEmpty()) throw new EmptyStackException();
            return data.get(data.size() - 1);
        }

        public boolean isEmpty() { return data.isEmpty(); }
        public int size() { return data.size(); }
        public String toString() { return data.toString(); }
    }

    public static <T> Stack<T> fromArray(T[] arr) {
        Stack<T> stack = new Stack<>();
        for (T item : arr) stack.push(item);
        return stack;
    }

    public static void main(String[] args) {
        Stack<Integer> stack = new Stack<>();
        stack.push(1); stack.push(2); stack.push(3);
        System.out.println("Stack: " + stack);    // [1, 2, 3]
        System.out.println("Peek: " + stack.peek()); // 3
        System.out.println("Pop: " + stack.pop());   // 3
        System.out.println("Size: " + stack.size()); // 2

        Stack<String> strStack = fromArray(new String[]{"x", "y", "z"});
        System.out.println("String stack: " + strStack); // [x, y, z]
    }
}
